mapper.select:
SELECT id, user_id, dataset_id, title, status, create_time, update_time
FROM analysis_session
WHERE id = #{id}

mapper.update:
UPDATE analysis_session
title = #{title}, status = #{status}, update_time = NOW()
WHERE id = #{id}

